from PyQt5.uic import loadUi
from PyQt5.QtWidgets import QApplication, QMessageBox, QTableWidgetItem
from pickle import dump, load
from random import randint
# -----------------------------------


def occ(ch):
    f1 = open("chaines.dat", "rb")
    occ = 0
    eof = False
    while not eof:
        try:
            e = load(f1)
            if e["id"] == ch:
                occ += 1
        except:
            eof = True
    f1.close()
    return occ


def recherche():
    if win.cat2.currentIndex() == 0 and win.nom2.text() == "":
        QMessageBox.critical(win, "erreur", "recherche invalide")
    else:
        cat2 = win.cat2.currentText()
        nom2 = win.nom2.text()
        f = open("chaines.dat", "rb")
        eof = False
        i = 0
        win.table_chaine.setRowCount(0)
        while not eof:
            try:
                e = load(f)
                if e["cat"] == cat2 or e["nom"] == nom2:
                    win.table_chaine.insertRow(i)
                    win.table_chaine.setItem(i, 0, QTableWidgetItem(e["id"]))
                    win.table_chaine.setItem(i, 1, QTableWidgetItem(e["nom"]))
                    win.table_chaine.setItem(i, 2, QTableWidgetItem(e["cat"]))
                    win.table_chaine.setItem(i, 3, QTableWidgetItem(e["qualite"]))
                    i += 1
            except:
                eof = True
        f.close()


def verif():
    ok = True
    id = win.id.text()
    nom = win.nom.text()
    cat = win.cat.currentIndex()
    co = win.co.isChecked()
    cn = win.cn.isChecked()
    url = win.url.text()

    if len(id) != 5 or not id.isdigit() or occ(id) > 0:
        QMessageBox.warning(win, "eurrure", "id invalide ")
        ok = False
    elif nom == "":
        QMessageBox.warning(win, "eurrure", " nom  invalide ")
        ok = False
    elif cat == 0:
        QMessageBox.warning(win, "eurrure", "cat invalide ")
        ok = False
    elif co == False and cn == False:
        QMessageBox.warning(win, "eurrure", " claire  invalide ")
        ok = False
    elif url == "":
        QMessageBox.warning(win, "eurrure", " claire  invalide ")
        ok = False
    return ok

# ----------------------------------------


def ajout_chaine():
    f1 = open("chaines.dat", "ab")
    if verif():
        e = {}
        e['id'] = win.id.text()
        e['nom'] = win.nom.text()
        e['cat'] = win.cat.currentText()
        if win.co.isChecked():
            e['claire'] = "O"
        else:
            e['claire'] = "N"
        e['url'] = win.url.text()
        if win.qt.isChecked():
            e['qualite'] = "4K"
        else:
            e['qualite'] = "HD"
        dump(e, f1)
        QMessageBox.information(win, "Succées", "Ajout est effectué avec Succées")
    f1.close()


def miseajour_code():
    f1 = open("chaines.dat", "rb")
    f2 = open("codes.dat", "wb")
    eof = False
    while not eof:
        try:
            e = load(f1)
            if e["claire"] == "N":
                e2 = {}
                e2["id"] = e["id"]
                e2["code"] = genrer_code(e["nom"])
                e2["valide"] = calcul_dure(e2["code"])
                dump(e2, f2)
                print(e2)
        except:
            eof = True
    f1.close()
    f2.close()


def conv_b10_b2(x):
    bin = ""
    while (x != 0):
        R = x % 2
        x = x // 2
        bin = str(R) + bin
    return bin


def conv_b2_b10(ch):
    j = 1
    s = 0
    for i in range(len(ch) - 1, -1, -1):
        s = s + int(ch[i]) * j
        j = j * 2
    return s


def affiche_code():
    f = open("codes.dat", "rb")
    eof = False
    i = 0
    win.table_code.setRowCount(0)
    while not eof:
        try:
            e = load(f)
            win.table_code.insertRow(i)
            win.table_code.setItem(i, 0, QTableWidgetItem(e["id"]))
            win.table_code.setItem(i, 1, QTableWidgetItem(e["code"]))
            win.table_code.setItem(i, 2, QTableWidgetItem(str(e["valide"])))
            i += 1
        except:
            eof = True
    f.close()


def genrer_code(ch):
    binch = ""
    bincle = ""
    res = ""
    for i in range(len(ch)):
        binch = binch + conv_b10_b2(ord(ch[i]))
    for i in range(len(binch)):
        bincle = bincle + str(randint(0, 1))
    for i in range(len(binch)):
        if binch[i] == bincle[i]:
            res += "0"
        else:
            res += "1"
    ch = ""
    while res != "":
        ch += chr(conv_b2_b10(res[0:8]))
        res = res[8:]
    return ch


def calcul_dure(ch):
    nb = 0
    for i in range(len(ch)):
        if not ("0" <= ch[i] <= "9" or "A" <= ch[i].upper() <= "Z"):
            nb += 1
    return nb * 10


def affiche_crypte():
    f1 = open("chaines.dat", "rb")
    eof = False
    win.list_chaine.clear()
    while not eof:
        try:
            e = load(f1)
            if e["claire"] == "N":
                win.list_chaine.addItem(e["id"] + "#" + e["nom"])
        except:
            eof = True
    f1.close()


app = QApplication([])
win = loadUi("interface_live.ui")
win.show()
win.btn1.clicked.connect(ajout_chaine)
win.btn2.clicked.connect(recherche)
win.btn3.clicked.connect(affiche_crypte)
win.btn4.clicked.connect(miseajour_code)
win.btn5.clicked.connect(affiche_code)
app.exec_()

